parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "ready_for_reporting": {
      "type": "boolean",
      "description": "True only when the current findings pass assurance; false when revision is needed."
    },
    "context": {
      "type": "string",
      "minLength": 1,
      "description": "Original question, current review requirements, complete latest findings and supplied evidence, HAF checks, limitations and correction requests."
    }
  },
  "required": [
    "ready_for_reporting",
    "context"
  ],
  "additionalProperties": false
}

parameters.jsCode:
const revision = $runIndex;
const item = $input.first();
const original = $('Workshop question').first().json.chatInput;
if (typeof original !== 'string' || !original.trim()) {
  throw new Error('Missing workshop question. Enter the question and run the workflow from the start.');
}
let prompt;
if (revision === 0) {
  prompt = 'INITIAL INVESTIGATION\nORIGINAL QUESTION\n' + original;
} else {
  const review = item.json.output;
  if (!review || typeof review !== 'object' || Array.isArray(review) ||
      review.ready_for_reporting !== false ||
      typeof review.context !== 'string' || !review.context.trim()) {
    throw new Error('Invalid HAF revision handoff. Expected output.ready_for_reporting=false and a non-empty output.context. Inspect the preceding HAF result; no Investigator call was made.');
  }
  if (revision >= 4) {
    throw new Error('HAF REVIEW UNRESOLVED: The initial investigation and three revisions are complete. No approved report was generated. Open the latest HAF Agent output and read CORRECTIONS REQUESTED for the remaining blockers.');
  }
  prompt = 'REVISION ' + revision + ' OF 3\nORIGINAL QUESTION\n' + original +
    '\n\nCURRENT HAF REQUIREMENTS AND CORRECTIONS\n' + review.context;
}
return [{json: {investigation_prompt: prompt, revision_number: revision}, pairedItem: {item: 0}}];
